<script setup lang="ts">
import { CHALLENGE_PHASES, type ChallengePhase } from '~/types/challenge'
import { downloadChallengeCsv, printChallengeReport, type ChallengeReportSection } from '~/utils/challengeExport'
import { weightedScore } from '~/utils/challengeScoring'
definePageMeta({ layout: 'challenge' })
const { state, ready, rankings, kpis, resetDemo } = useChallenge()
const { t } = useI18n()
const { lt, number, date } = useChallengeFormat()
const { result, push } = useChallengeToast()
useHead(() => ({ title: `${t('challenge.admin.reportsTitle')} - Gaming Lab` }))
const previewOpen = ref(false)
const resetOpen = ref(false)
const resetPhase = ref<ChallengePhase>('team_formation')
const rankingHeaders = computed(() => ['rank', 'team', 'school', 'average', 'evaluationCount', 'spread'].map(key => t(`challenge.admin.${key}`)))
const rankingRows = computed(() => rankings.value.map(row => { const team = state.value!.teams.find(item => item.id === row.teamId); return [row.rank, lt(team?.name), lt(state.value!.schools.find(school => school.id === team?.schoolId)?.name), row.score, row.evaluationCount, row.spread] }))
const evaluationHeaders = computed(() => [t('challenge.admin.team'), t('challenge.admin.judge'), ...((state.value?.criteria || []).map(item => lt(item.name))), t('challenge.admin.average'), t('challenge.admin.evaluationStatus'), t('challenge.admin.strengths'), t('challenge.admin.improvements'), t('challenge.admin.recommendation'), t('challenge.admin.updatedAt')])
const evaluationRows = computed(() => state.value?.evaluations.map(item => [lt(state.value!.teams.find(team => team.id === item.teamId)?.name), lt(state.value!.judges.find(judge => judge.id === item.judgeId)?.name), ...state.value!.criteria.map(criterion => item.scores[criterion.id] ?? ''), weightedScore(item, state.value!.criteria), t(`challenge.status.${item.status}`), item.strengths, item.improvements, item.recommendation, date(item.updatedAt, { dateStyle: 'short', timeStyle: 'short' })]) || [])
const sections = computed<ChallengeReportSection[]>(() => [
  { heading: t('challenge.admin.competitionSummary'), headers: [t('challenge.admin.metric'), t('challenge.admin.value')], rows: [[t('challenge.admin.currentPhase'), t(`challenge.phases.${state.value?.competition.phase}`)], [t('challenge.admin.schools'), kpis.value.schools], [t('challenge.admin.teams'), kpis.value.teams], [t('challenge.admin.students'), kpis.value.students], [t('challenge.admin.submissions'), kpis.value.submissions], [t('challenge.admin.completedEvaluations'), kpis.value.completedEvaluations], [t('challenge.admin.publicVisibility'), t(`challenge.status.${state.value?.competition.resultsVisibility}`)], [t('challenge.admin.generatedAt'), date(new Date(), { dateStyle: 'medium', timeStyle: 'short' })]] },
  { heading: t('challenge.admin.rankingExport'), headers: rankingHeaders.value, rows: rankingRows.value },
  { heading: t('challenge.admin.evaluationExport'), headers: evaluationHeaders.value, rows: evaluationRows.value },
])
const download = (kind: 'rankings' | 'evaluations') => { const ok = downloadChallengeCsv(`challenge-${kind}.csv`, kind === 'rankings' ? rankingHeaders.value : evaluationHeaders.value, kind === 'rankings' ? rankingRows.value : evaluationRows.value); push(ok ? 'challenge.admin.exportDownloaded' : 'challenge.toasts.failed', ok ? 'success' : 'danger') }
const print = () => { if (!printChallengeReport(lt(state.value?.competition.title), sections.value)) push('challenge.admin.popupBlocked', 'warning') }
const reset = () => { result(resetDemo(resetPhase.value), 'challenge.toasts.reset'); resetOpen.value = false; previewOpen.value = false }
</script>
<template>
  <div v-if="ready && state" class="challenge-page space-y-8"><div><h1 class="challenge-heading">{{ $t('challenge.admin.reportsTitle') }}</h1><p class="challenge-subtitle">{{ $t('challenge.admin.reportsIntro') }}</p></div>
    <section class="challenge-panel"><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.downloadData') }}</h2><div class="mt-5 divide-y divide-gray-100"><div class="flex flex-wrap items-center justify-between gap-4 py-5"><div><h3 class="font-bold">{{ $t('challenge.admin.rankingExport') }}</h3><p class="mt-2 text-sm">{{ $t('challenge.admin.rankingExportHint', { count: number(rankingRows.length) }) }}</p></div><button type="button" class="challenge-button-secondary" :disabled="!rankingRows.length" @click="download('rankings')"><AppIcon name="download" class="h-4 w-4" />{{ $t('challenge.admin.downloadCsv') }}</button></div><div class="flex flex-wrap items-center justify-between gap-4 py-5"><div><h3 class="font-bold">{{ $t('challenge.admin.evaluationExport') }}</h3><p class="mt-2 text-sm">{{ $t('challenge.admin.evaluationExportHint', { count: number(evaluationRows.length) }) }}</p></div><button type="button" class="challenge-button-secondary" :disabled="!evaluationRows.length" @click="download('evaluations')"><AppIcon name="download" class="h-4 w-4" />{{ $t('challenge.admin.downloadCsv') }}</button></div></div><p class="mt-4 text-xs leading-relaxed">{{ $t('challenge.admin.csvHint') }}</p></section>
    <section class="challenge-panel"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.summaryReport') }}</h2><p class="mt-2 max-w-2xl text-sm leading-relaxed">{{ $t('challenge.admin.summaryHint') }}</p></div><button type="button" class="challenge-button" @click="previewOpen = true"><AppIcon name="eye" class="h-4 w-4" />{{ $t('challenge.admin.previewReport') }}</button></div></section>
    <section class="rounded-2xl border border-red-200 bg-white p-6"><h2 class="text-xl font-bold text-red-800">{{ $t('challenge.admin.dangerZone') }}</h2><p class="mt-3 max-w-2xl text-sm leading-relaxed">{{ $t('challenge.shell.resetWarning') }}</p><div class="mt-5 flex flex-wrap items-end gap-4"><div class="w-full sm:max-w-xs"><label for="reports-reset-phase" class="challenge-label">{{ $t('challenge.shell.resetPhase') }}</label><select id="reports-reset-phase" v-model="resetPhase" class="challenge-field"><option v-for="phase in CHALLENGE_PHASES" :key="phase" :value="phase">{{ $t(`challenge.phases.${phase}`) }}</option></select></div><button type="button" class="challenge-button-secondary !border-red-200 !text-red-800" @click="resetOpen = true"><AppIcon name="refresh" class="h-4 w-4" />{{ $t('challenge.shell.reset') }}</button></div></section>
    <ChallengeModal v-model="previewOpen" :title="$t('challenge.admin.summaryReport')" wide><div class="space-y-7"><section v-for="section in sections" :key="section.heading"><h3 class="mb-3 font-bold">{{ section.heading }}</h3><div class="max-h-72 overflow-auto rounded-xl border border-gray-200"><table class="w-full text-sm"><thead class="bg-brand/5"><tr><th v-for="(header, index) in section.headers" :key="index" class="min-w-24 px-3 py-3 text-start">{{ header }}</th></tr></thead><tbody><tr v-for="(row, rowIndex) in section.rows" :key="rowIndex" class="border-t border-gray-100"><td v-for="(cell, cellIndex) in row" :key="cellIndex" class="px-3 py-3">{{ cell }}</td></tr><tr v-if="!section.rows.length"><td :colspan="section.headers.length" class="p-5">{{ $t('challenge.admin.noReportRows') }}</td></tr></tbody></table></div></section><div class="flex justify-end gap-3"><button type="button" class="challenge-button-secondary" @click="previewOpen = false">{{ $t('challenge.shell.close') }}</button><button type="button" class="challenge-button" @click="print">{{ $t('challenge.admin.printReport') }}</button></div></div></ChallengeModal>
    <ChallengeConfirm v-model="resetOpen" :title="$t('challenge.shell.reset')" :message="$t('challenge.shell.resetWarning')" @confirm="reset" />
  </div><ChallengePageSkeleton v-else />
</template>
